#!/usr/bin/env bash
set -Eeuo pipefail
cd "$(dirname "$0")/.."

test_id="nofx-check-$$"
app="$test_id-app"
db="$test_id-db"
network="$test_id-network"
image="nofx-render:verification"
temp_dir=$(mktemp -d)
cleanup() {
    status=$?
    trap - EXIT
    if [[ $status -ne 0 ]]; then docker logs "$app" 2>/dev/null || true; fi
    docker rm -f "$app" "$db" >/dev/null 2>&1 || true
    docker network rm "$network" >/dev/null 2>&1 || true
    # Only the temporary files generated by this verification are removed.
    rm -rf "$temp_dir"
    exit "$status"
}
trap cleanup EXIT

docker build -f Dockerfile.render -t "$image" .
docker network create "$network" >/dev/null
docker run -d --name "$db" --network "$network" \
    -e POSTGRES_PASSWORD=verification-admin-password postgres:17-alpine >/dev/null
ready=false
for ((attempt=0; attempt<60; attempt++)); do
    if docker exec "$db" pg_isready -U postgres >/dev/null 2>&1; then ready=true; break; fi
    sleep 1
done
[[ $ready == true ]]
docker exec -i "$db" psql -U postgres -v ON_ERROR_STOP=1 <<'SQL'
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE SCHEMA auth;
CREATE TABLE auth.users (id uuid PRIMARY KEY);
SQL
docker exec -i -e NOFX_DB_PASSWORD=verification-db-password "$db" \
    psql -U postgres -f - < render/supabase-bootstrap.sql

openssl genrsa 2048 > "$temp_dir/rsa.pem" 2>/dev/null
python3 - "$temp_dir" "$db" <<'PY'
import json, pathlib, secrets, sys
directory = pathlib.Path(sys.argv[1])
values = {
    'DB_HOST': sys.argv[2], 'DB_USER': 'nofx_app',
    'DB_PASSWORD': 'verification-db-password', 'DB_SSLMODE': 'disable',
    'JWT_SECRET': secrets.token_urlsafe(48),
    'DATA_ENCRYPTION_KEY': secrets.token_urlsafe(32),
    'RSA_PRIVATE_KEY': directory.joinpath('rsa.pem').read_text().replace('\n', r'\n'),
    'CORS_ALLOWED_ORIGINS': 'https://nofx-verification.example',
}
env_file = directory / 'app.env'
env_file.write_text(''.join(f'{key}={value}\n' for key, value in values.items()))
env_file.chmod(0o600)
PY
docker run -d --name "$app" --network "$network" \
    --env-file "$temp_dir/app.env" -p 127.0.0.1::10000 "$image" >/dev/null
wait_for_app() {
    ready=false
    for ((attempt=0; attempt<150; attempt++)); do
        if docker exec "$app" wget -q -O /dev/null http://127.0.0.1:10000/health 2>/dev/null; then
            ready=true; break
        fi
        [[ $(docker inspect -f '{{.State.Running}}' "$app") == true ]] || return 1
        sleep 1
    done
    [[ $ready == true ]]
}
wait_for_app
address=$(docker port "$app" 10000/tcp)
python3 render/verify-http.py "http://$address"

result=$(docker exec "$db" psql -U postgres -Atqc \
    "SELECT count(*) > 0 AND bool_and(relrowsecurity) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='nofx' AND c.relkind='r'")
[[ $result == t ]]
result=$(docker exec "$db" psql -U postgres -Atqc \
    "SELECT NOT has_schema_privilege('anon','nofx','USAGE') AND NOT has_schema_privilege('authenticated','nofx','USAGE') AND NOT has_schema_privilege('nofx_app','auth','USAGE')")
[[ $result == t ]]

docker restart "$app" >/dev/null
wait_for_app
# Docker can allocate a different ephemeral host port when restarting.
address=$(docker port "$app" 10000/tcp)
python3 render/verify-http.py "http://$address" --after-restart

# A dead API must take the whole service down instead of passing static health.
docker exec "$app" sh -c 'kill -TERM "$(pidof nofx)"'
for ((attempt=0; attempt<30; attempt++)); do
    if [[ $(docker inspect -f '{{.State.Running}}' "$app") == false ]]; then
        echo 'Verified: frontend, PostgreSQL isolation, login, restart persistence, and process supervision.'
        exit 0
    fi
    sleep 1
done
echo 'Container stayed running after its backend exited.' >&2
exit 1
